import React from "react";
import "./../css/RequestDetails.css";

import {
  FaArrowRight,
  FaTag,
  FaUserCircle,
  FaUser,
  FaPhone,
  FaMobileAlt,
  FaMapMarkerAlt,
  FaMapMarkedAlt,
  FaMicrochip,
  FaShieldAlt,
  FaQuestionCircle,
  FaClock,
  FaLink,
  FaFileAlt,
  FaMoneyBillWave,
  FaTools,
  FaPercentage,
  FaExclamationCircle,
  FaPlus,
  FaComments,
  FaReceipt,
  FaCopy,
} from "react-icons/fa";

class RequestDetails extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      request: {
        requestNumber: "1405050027",
        technicianName: "علی عبداللهی",
        customerName: "مخاخری",
        mobile: "09121457004",
        landline: "---",
        province: "تهران",
        address: "شهریار بعدیل بادامک یاسک ۶ امورز",
        deviceType: "ساید",
        brand: "سامسونگ_SAMSUNG",
        deviceProblem: "یخچال گرم و لاستیک",
        visitDate: "1405/05/28",
        description: "",
        status: "تسویه شده",

        totalReceived: "۲۸,۰۰۰,۰۰۰ تومان",
        consumableCost: "۴,۰۰۰,۰۰۰ تومان",
        consumables:
          "لاستیک درب، فیلترها، ترموویزر، سنسور",
        totalWage: "۲۴,۰۰۰,۰۰۰ تومان",
        commission: "۱۲,۰۰۰,۰۰۰ تومان",

        receiptImage:
          "https://via.placeholder.com/300x220?text=Payment+Receipt",

        settlementDescription: "تایید است",

        relatedRequests: [],
      },

      copied: false,
    };
  }

  componentDidMount() {
    /*
      بعداً API را اینجا وصل کن.

      مثال:

      const requestId = this.props.match?.params?.id;

      fetch(`/api/requests/${requestId}`)
        .then((response) => response.json())
        .then((data) => {
          this.setState({
            request: data
          });
        });
    */
  }

  handleBack = () => {
    window.history.back();
  };

  // کپی شماره درخواست
  handleCopyRequestNumber = async () => {
    const { request } = this.state;

    try {
      await navigator.clipboard.writeText(request.requestNumber);

      this.setState({ copied: true });

      setTimeout(() => {
        this.setState({ copied: false });
      }, 1500);
    } catch (error) {
      console.log("خطا در کپی شماره درخواست:", error);
    }
  };

  // باز کردن پروفایل تعمیرکار
  handleOpenProfile = () => {
    /*
      کامپوننت پروفایل را بعداً از Parent باز کن.

      مثال در Parent:

      <RequestDetails
        onOpenProfile={(technician) => {
          this.setState({
            showProfile: true,
            selectedTechnician: technician
          });
        }}
      />

      اینجا فقط دکمه را اجرا می‌کنیم.
    */

    if (this.props.onOpenProfile) {
      this.props.onOpenProfile(this.state.request);
    }
  };

  // تماس با تعمیرکار
handleCallTechnician = () => {
  const { mobile } = this.state.request;

  if (!mobile) return;

  window.location.href = `tel:${mobile}`;
};

  handleAddRelatedRequest = () => {
    /*
      بعداً API افزودن درخواست مرتبط اینجا قرار می‌گیرد.
    */
  };

  renderInfo = (
    icon,
    title,
    value,
    extraClass = "",
    action = null
  ) => {
    const Icon = icon;

    return (
      <div className="request-detail-box">

        <div className="request-detail-icon">
          <Icon />
        </div>

        <div className="request-detail-text">

          <span className="request-detail-title">
            {title}:
          </span>

          <span
            className={`request-detail-value ${extraClass}`}
          >
            {value || ""}
          </span>

        </div>

        {action && (
          <div className="request-detail-action">
            {action}
          </div>
        )}

      </div>
    );
  };

  render() {
    const {
      request,
      copied,
    } = this.state;

    return (
      <div className="request-details-page container">

        {/* Header */}

        <div className="request-top-bar">

          <button
            type="button"
            className="request-back-btn"
            onClick={this.handleBack}
          >
            <FaArrowRight />
          </button>

          <div className="request-top-icon">
            <FaComments />
          </div>

        </div>

        {/* شماره درخواست + کپی */}

        {this.renderInfo(
          FaTag,
          "شماره درخواست",
          request.requestNumber,
          "",
          <button
            type="button"
            className={`detail-action-btn ${
              copied ? "copied" : ""
            }`}
            onClick={this.handleCopyRequestNumber}
            title="کپی شماره درخواست"
          >
            <FaCopy />

            {copied && (
              <span className="copy-tooltip">
                کپی شد
              </span>
            )}
          </button>
        )}

        {/* نام تعمیرکار + پروفایل */}

        {this.renderInfo(
          FaUserCircle,
          "نام تعمیرکار",
          request.technicianName,
          "",
          <button
            type="button"
            className="detail-action-btn"
            onClick={this.handleOpenProfile}
            title="مشاهده پروفایل"
          >
            <FaUser />
          </button>
        )}

        {/* نام مشتری */}

        {this.renderInfo(
          FaUser,
          "نام مشتری",
          request.customerName
        )}

        {/* شماره تماس + تماس */}

        {this.renderInfo(
          FaPhone,
          "شماره تماس",
          request.mobile,
          "",
          <button
            type="button"
            className="detail-action-btn call-action"
            onClick={this.handleCallTechnician}
            title="تماس با تعمیرکار"
          >
            <FaPhone />
          </button>
        )}

        {/* تلفن ثابت */}

        {this.renderInfo(
          FaMobileAlt,
          "تلفن ثابت",
          request.landline
        )}

        {/* استان */}

        {this.renderInfo(
          FaMapMarkerAlt,
          "استان",
          request.province
        )}

        {/* آدرس */}

        {this.renderInfo(
          FaMapMarkedAlt,
          "آدرس",
          request.address
        )}

        {/* نوع دستگاه */}

        {this.renderInfo(
          FaMicrochip,
          "نوع دستگاه",
          request.deviceType
        )}

        {/* برند دستگاه */}

        {this.renderInfo(
          FaShieldAlt,
          "برند دستگاه",
          request.brand
        )}

        {/* ایراد دستگاه */}

        {this.renderInfo(
          FaQuestionCircle,
          "ایراد دستگاه",
          request.deviceProblem
        )}

        {/* زمان مراجعه */}

        {this.renderInfo(
          FaClock,
          "زمان مراجعه",
          request.visitDate
        )}

        {/* توضیحات */}

        {this.renderInfo(
          FaLink,
          "توضیحات",
          request.description
        )}

        {/* وضعیت */}

        {this.renderInfo(
          FaFileAlt,
          "وضعیت",
          request.status,
          "request-status"
        )}

        {/* کل دریافتی */}

        {this.renderInfo(
          FaMoneyBillWave,
          "کل دریافتی",
          request.totalReceived
        )}

        {/* هزینه لوازم مصرفی */}

        {this.renderInfo(
          FaMoneyBillWave,
          "هزینه لوازم مصرفی",
          request.consumableCost
        )}

        {/* لوازم مصرفی */}

        {this.renderInfo(
          FaTools,
          "لوازم مصرفی",
          request.consumables
        )}

        {/* کل اجرت */}

        {this.renderInfo(
          FaPercentage,
          "کل اجرت",
          request.totalWage
        )}

        {/* پورسانت */}

        {this.renderInfo(
          FaPercentage,
          "پورسانت (50%)",
          request.commission
        )}

        {/* فیش واریزی */}

        <div className="request-detail-box request-receipt-box">

          <div className="request-detail-icon">
            <FaReceipt />
          </div>

          <div className="request-receipt-content">

            <div className="request-receipt-title row">

              <div className="col-3">
                فیش واریزی:
              </div>

              <div className="col-8">

                <img
                  src={request.receiptImage}
                  alt="فیش واریزی"
                  className="request-receipt-image me-4"
                />

              </div>

            </div>

          </div>

        </div>

        {/* توضیحات تایید تسویه */}

        {this.renderInfo(
          FaExclamationCircle,
          "توضیحات تایید تسویه",
          request.settlementDescription
        )}

        {/* درخواست های مرتبط */}

        <div className="related-section">

          <div className="related-title text-center">
            درخواست های مرتبط:
          </div>

          {request.relatedRequests.length === 0 ? (

            <div className="related-empty">

              <div className="related-empty-icon">
                <FaLink />
              </div>

              <div>
                هنوز موردی برای نمایش وجود ندارد.
              </div>

            </div>

          ) : (

            request.relatedRequests.map((item) => (
              <div
                key={item.id}
                className="request-detail-box"
              >
                {item.title}
              </div>
            ))

          )}

          <button
            type="button"
            className="related-add-btn"
            onClick={this.handleAddRelatedRequest}
          >
            <FaPlus className="ms-2" />
            افزودن درخواست مرتبط
          </button>

        </div>

      </div>
    );
  }
}

export default RequestDetails;
